// Akış şemasının saf mantığı: sütun, sıra, boyut yerleşimi ve yazımlar. DOM'a dokunmaz, test edilebilir.
// Sayılar ABACUS'tandır (chart-format): adet "1.234", tutar "₺1.250.000", kısa tutar "₺1,25Mn", pay "%41,6".
import { formatMoney, formatMoneyCompact, formatNumber, formatRatio } from "../lib/chart-format";

/** `muted`: düşen kol gibi ikincil düğüm; nötr gri çizilir ve ona giren şeritler de gri olur. */
export interface SankeyNodeInput { id: string; label: string; muted?: boolean }
export interface SankeyLinkInput { source: string; target: string; value: number }
export type SankeyKind = "count" | "money";

export interface LaidNode {
  id: string; label: string; column: number; order: number;
  /** Gelenle gidenin büyüğü. */
  value: number;
  /** Düğümün genişlik ekseni üzerindeki başlangıcı ve boyu (piksel). */
  start: number; size: number;
  /** Renk sırası: ilk sütunda kendi sırası, sonrakilerde en büyük gelen akışın kaynağınınki. */
  tone: number;
  muted: boolean;
}
export interface LaidLink {
  id: string; source: string; target: string; value: number;
  /** Şeridin orta çizgisinin iki uçtaki konumu ve kalınlığı (piksel). */
  sourceAt: number; targetAt: number; thickness: number;
}
export interface SankeyLayout { nodes: LaidNode[]; links: LaidLink[]; columns: number; total: number }

/** Akışlar yalnız pozitif değerli, düğümleri bilinen ve kendine dönmeyen bağlantılardır. */
export function validLinks(nodes: SankeyNodeInput[], links: SankeyLinkInput[]): SankeyLinkInput[] {
  const known = new Set(nodes.map(node => node.id));
  return links.filter(link => link.value > 0 && known.has(link.source) && known.has(link.target) && link.source !== link.target);
}

/** Her düğümün sütunu: kaynaktan en uzun yolun uzunluğu. Döngü varsa düğüm sayısı kadar turdan sonra durur. */
export function columnsOf(nodes: SankeyNodeInput[], links: SankeyLinkInput[]): Map<string, number> {
  const column = new Map(nodes.map(node => [node.id, 0]));
  for (let pass = 0; pass < nodes.length; pass++) {
    let changed = false;
    for (const link of links) {
      const next = (column.get(link.source) ?? 0) + 1;
      if (next > (column.get(link.target) ?? 0) && next < nodes.length) { column.set(link.target, next); changed = true; }
    }
    if (!changed) break;
  }
  return column;
}

/** `breadth`: şemanın genişlik ekseni uzunluğu (yatay şemada yükseklik). `gap`: aynı sütundaki düğümler arası boşluk. */
export function layoutSankey(nodes: SankeyNodeInput[], rawLinks: SankeyLinkInput[], breadth: number, gap = 10): SankeyLayout {
  const links = validLinks(nodes, rawLinks);
  const used = new Set(links.flatMap(link => [link.source, link.target]));
  const active = nodes.filter(node => used.has(node.id));
  if (!active.length) return { nodes: [], links: [], columns: 0, total: 0 };
  const column = columnsOf(active, links);
  const columns = Math.max(...column.values()) + 1;
  const inSum = new Map<string, number>(), outSum = new Map<string, number>();
  for (const link of links) {
    outSum.set(link.source, (outSum.get(link.source) ?? 0) + link.value);
    inSum.set(link.target, (inSum.get(link.target) ?? 0) + link.value);
  }
  const valueOf = (id: string) => Math.max(inSum.get(id) ?? 0, outSum.get(id) ?? 0);

  // Sütun içi sıra: girdi sırasından başlar, komşuların ortalama sırasına göre birkaç tur düzeltilir (kesişimi azaltır).
  const byColumn: SankeyNodeInput[][] = Array.from({ length: columns }, () => []);
  for (const node of active) byColumn[column.get(node.id)!]!.push(node);
  const position = new Map<string, number>();
  const refresh = () => byColumn.forEach(list => list.forEach((node, at) => position.set(node.id, list.length > 1 ? at / (list.length - 1) : .5)));
  refresh();
  for (let sweep = 0; sweep < 4; sweep++) {
    const order = sweep % 2 === 0 ? byColumn.map((_, at) => at) : byColumn.map((_, at) => columns - 1 - at);
    for (const at of order) {
      const forward = sweep % 2 === 0;
      const barycenter = new Map<string, number>();
      for (const node of byColumn[at]!) {
        const near = links.filter(link => forward ? link.target === node.id : link.source === node.id);
        const weight = near.reduce((sum, link) => sum + link.value, 0);
        barycenter.set(node.id, weight ? near.reduce((sum, link) => sum + link.value * (position.get(forward ? link.source : link.target) ?? .5), 0) / weight : position.get(node.id) ?? .5);
      }
      byColumn[at]!.sort((a, b) => barycenter.get(a.id)! - barycenter.get(b.id)!);
      refresh();
    }
  }

  const scale = Math.min(...byColumn.map(list => {
    const sum = list.reduce((acc, node) => acc + valueOf(node.id), 0);
    return Math.max(0, breadth - gap * (list.length - 1)) / sum;
  }));
  const laid = new Map<string, LaidNode>();
  byColumn.forEach((list, at) => {
    const sizes = list.map(node => valueOf(node.id) * scale);
    const used2 = sizes.reduce((sum, size) => sum + size, 0) + gap * (list.length - 1);
    let cursor = Math.max(0, (breadth - used2) / 2);
    list.forEach((node, order) => {
      laid.set(node.id, { id: node.id, label: node.label, column: at, order, value: valueOf(node.id), start: cursor, size: sizes[order]!, tone: 0, muted: !!node.muted });
      cursor += sizes[order]! + gap;
    });
  });

  // Renk sırası.
  let nextTone = 0;
  for (const node of byColumn[0]!) laid.get(node.id)!.tone = nextTone++;
  for (let at = 1; at < columns; at++) {
    for (const node of byColumn[at]!) {
      const biggest = links.filter(link => link.target === node.id).sort((a, b) => b.value - a.value)[0];
      laid.get(node.id)!.tone = biggest ? laid.get(biggest.source)!.tone : nextTone++;
    }
  }

  // Şerit uçları: her düğümde giden akışlar hedeflerin konumuna, gelenler kaynakların konumuna göre dizilir.
  const outCursor = new Map<string, number>(), inCursor = new Map<string, number>();
  laid.forEach(node => { outCursor.set(node.id, node.start); inCursor.set(node.id, node.start); });
  const result: LaidLink[] = [];
  const sortedOut = [...links].sort((a, b) => laid.get(a.target)!.start - laid.get(b.target)!.start);
  const sourceAt = new Map<LaidLink["id"], number>();
  const idOf = (link: SankeyLinkInput) => `${link.source}>${link.target}`;
  for (const link of sortedOut) {
    const thickness = link.value * scale, from = outCursor.get(link.source)!;
    sourceAt.set(idOf(link), from + thickness / 2);
    outCursor.set(link.source, from + thickness);
  }
  const sortedIn = [...links].sort((a, b) => laid.get(a.source)!.start - laid.get(b.source)!.start);
  for (const link of sortedIn) {
    const thickness = link.value * scale, to = inCursor.get(link.target)!;
    result.push({ id: idOf(link), source: link.source, target: link.target, value: link.value, sourceAt: sourceAt.get(idOf(link))!, targetAt: to + thickness / 2, thickness });
    inCursor.set(link.target, to + thickness);
  }
  const total = byColumn[0]!.reduce((sum, node) => sum + valueOf(node.id), 0);
  return { nodes: [...laid.values()], links: result, columns, total };
}

/** Vurgulanacak yol: verilen uçtan geriye (kaynaklara) ve ileriye (hedeflere) tüm bağlantılar. */
export function pathThrough(links: Pick<LaidLink, "id" | "source" | "target">[], upstreamFrom: string | null, downstreamFrom: string | null): { links: Set<string>; nodes: Set<string> } {
  const linkIds = new Set<string>(), nodeIds = new Set<string>();
  const walk = (start: string | null, direction: "up" | "down") => {
    if (!start) return;
    nodeIds.add(start);
    const queue = [start], seen = new Set([start]);
    while (queue.length) {
      const id = queue.shift()!;
      for (const link of links) {
        const matches = direction === "up" ? link.target === id : link.source === id;
        if (!matches) continue;
        linkIds.add(link.id);
        const next = direction === "up" ? link.source : link.target;
        nodeIds.add(next);
        if (!seen.has(next)) { seen.add(next); queue.push(next); }
      }
    }
  };
  walk(upstreamFrom, "up");
  walk(downstreamFrom, "down");
  return { links: linkIds, nodes: nodeIds };
}

/** Değer yazımı: adet "1.234" ya da TRY "₺1.250.000". */
export const flowValueText = (kind: SankeyKind, value: number) => kind === "money" ? formatMoney(value, 0) : formatNumber(value, 0);
/** Düğüm yanındaki kısa yazım: adet "12,5B" değil tam sayı, tutar "₺1,25Mn". */
export const flowShortText = (kind: SankeyKind, value: number) => kind === "money" ? formatMoneyCompact(value) : formatNumber(value, 0);
/** Pay: 0,416 → "%41,6". Oran hesabı düz bölmedir. */
export const flowShareText = (value: number, base: number) => formatRatio(base > 0 ? value / base : 0, 1);

/** Akış ipucu: "Reklam → Site: 1.200 (kaynağın payı %40)". */
export function linkTip(kind: SankeyKind, sourceLabel: string, targetLabel: string, value: number, sourceValue: number): string {
  return `${sourceLabel} → ${targetLabel}: ${flowValueText(kind, value)} (kaynağın payı ${flowShareText(value, sourceValue)})`;
}
export function nodeTip(kind: SankeyKind, label: string, value: number, total: number): string {
  return `${label}: ${flowValueText(kind, value)} (toplamın payı ${flowShareText(value, total)})`;
}

.figure { display: grid; min-width: 0; gap: var(--space-4); margin: 0; color: var(--foreground); }
.head { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.titles { min-width: 0; }
.title { font-family: var(--font-display); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-display); }
.description { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.actions { display: flex; gap: var(--space-2); }
.heads { position: relative; height: 1.25rem; margin-bottom: calc(var(--space-2) * -1); }
.headLabel { position: absolute; transform: translateX(-50%); color: var(--text-muted); font-size: var(--text-xs); white-space: nowrap; }
.stage { position: relative; min-width: 0; }
.focus { outline: none; border-radius: var(--radius-control); }
.focus:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.svg { display: block; max-width: 100%; overflow: visible; }
.ribbon { fill: none; opacity: .32; stroke-linecap: butt; transition: opacity var(--duration-fast) var(--ease-standard), stroke-width var(--duration-considered) var(--ease-standard), d var(--duration-considered) var(--ease-standard); }
.ribbon[data-lit] { opacity: .72; }
.ribbon[data-dim] { opacity: .08; }
.ribbons { clip-path: inset(0 100% 0 0); transition: clip-path var(--duration-considered) var(--ease-enter); }
.svg[data-revealed] .ribbons { clip-path: inset(0 0 0 0); }
.dot { fill: var(--surface); opacity: .85; pointer-events: none; }
.node { cursor: default; transition: opacity var(--duration-fast) var(--ease-standard); }
.node[data-dim] { opacity: .35; }
.rect { transition: y var(--duration-considered) var(--ease-standard), height var(--duration-considered) var(--ease-standard); }
.node[data-selected] .rect { stroke: var(--foreground); stroke-width: 1.5; }
.nodeText { fill: var(--foreground); font-size: var(--text-xs); paint-order: stroke; stroke: var(--surface); stroke-width: 3px; stroke-linejoin: round; pointer-events: none; }
.nodeName { font-weight: 500; }
.nodeValue { fill: var(--text-secondary); font-variant-numeric: tabular-nums; }
.tip { position: absolute; z-index: 1; max-width: 18rem; padding: var(--space-1) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-raised); box-shadow: var(--shadow-raised); font-size: var(--text-xs); pointer-events: none; transform: translate(12px, 12px); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.skeleton { height: 14rem; border-radius: var(--radius-control); background: var(--surface-muted); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.figure[data-reduced] .ribbon, .figure[data-reduced] .ribbons, .figure[data-reduced] .rect, .figure[data-reduced] .node { transition: none; }
@media (prefers-reduced-motion: reduce) { .ribbon, .ribbons, .rect, .node { transition: none; } }

"use client";

import { useEffect, useId, useMemo, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { seriesColor, useElementWidth, useOnScreen, useReducedMotionSafe } from "../lib/viz-utils";
import { Switch } from "../switch/switch";
import { flowShareText, flowShortText, flowValueText, layoutSankey, linkTip, nodeTip, pathThrough, type SankeyKind, type SankeyLinkInput, type SankeyNodeInput } from "./sankey-flow-format";
import styles from "./sankey-flow.module.css";

export type { SankeyKind, SankeyLinkInput, SankeyNodeInput };

/** Bir toplamın aşamalar boyunca nasıl bölündüğünü ve birleştiğini göstermek için kullanın; dallanmayan doğrusal yol için huni, katı ağaç için ağaç haritası daha doğrudur. */
export interface SankeyFlowProps {
  nodes: SankeyNodeInput[];
  links: SankeyLinkInput[];
  /** Neyin aktığı, örneğin "Nakit akışı". Grafiği yardımcı teknolojiye adlandırır. */
  label: string;
  description?: string;
  /** Sütun başlıkları, soldan sağa ("Kaynak", "Hesap", "Gider"). Sığmazsa gizlenir. */
  columnLabels?: string[];
  /** "count": adet ("1.234"); "money": TRY tutar ("₺1.250.000"). */
  kind?: SankeyKind;
  /** Sağ üstte duran denetimler (dönem seçici gibi). */
  actions?: ReactNode;
  /** Sabitlenmiş (seçili) düğüm; denetimli kullanım için. Tıklama ve Enter seçer, Esc kaldırır. */
  selectedId?: string | null;
  onSelectedChange?: (id: string | null) => void;
  /** Başlık satırını gizler (üst blok kendi başlığını yazıyorsa); ad yine ekran okuyucuya söylenir. */
  bare?: boolean;
  loading?: boolean;
  emptyText?: string;
}

type Focus = { type: "node" | "link"; id: string } | null;
const NODE = 12, MARGIN = 112, HEIGHT = 340, NARROW = 420;

export function SankeyFlow({ nodes, links, label, description, columnLabels, kind = "count", actions, selectedId, onSelectedChange, bare = false, loading = false, emptyText = "Henüz akış yok." }: SankeyFlowProps) {
  const reduced = useReducedMotionSafe();
  const titleId = useId();
  const [box, width] = useElementWidth<HTMLDivElement>();
  const [visibleRef, onScreen] = useOnScreen<HTMLElement>();
  const [flow, setFlow] = useState(true);
  const [focus, setFocus] = useState<Focus>(null);
  const [tip, setTip] = useState<{ x: number; y: number; text: string } | null>(null);
  const [revealed, setRevealed] = useState(false);
  useEffect(() => { const frame = requestAnimationFrame(() => setRevealed(true)); return () => cancelAnimationFrame(frame); }, []);

  const vertical = width > 0 && width < NARROW;
  const probe = useMemo(() => layoutSankey(nodes, links, 100), [nodes, links]);
  const columns = probe.columns;
  const length = vertical ? Math.max(260, columns * 110) : width;
  const breadth = vertical ? Math.max(120, width - 16) : HEIGHT - 8;
  const layout = useMemo(() => layoutSankey(nodes, links, breadth), [nodes, links, breadth]);
  const nodeById = useMemo(() => new Map(layout.nodes.map(node => [node.id, node])), [layout]);

  // Sütun konumu (akış ekseni); ilk ve son sütunun etiketleri kenar boşluklarına yazılır.
  const margin = vertical ? 8 : MARGIN;
  const alongOf = (column: number) => layout.columns > 1 ? margin + (column * (length - 2 * margin - NODE)) / (layout.columns - 1) : (length - NODE) / 2;
  const point = (along: number, across: number) => vertical ? { x: across + 8, y: along } : { x: along, y: across + 4 };

  const through = useMemo(() => {
    const active: Focus = focus ?? (selectedId ? { type: "node", id: selectedId } : null);
    if (!active) return null;
    if (active.type === "node") return pathThrough(layout.links, active.id, active.id);
    const link = layout.links.find(item => item.id === active.id);
    return link ? pathThrough(layout.links, link.source, link.target) : null;
  }, [focus, layout, selectedId]);

  const colorOf = (id: string) => nodeById.get(id)?.muted ? "var(--neutral-6)" : seriesColor(nodeById.get(id)?.tone ?? 0);
  const linkColor = (link: { source: string; target: string }) => nodeById.get(link.target)?.muted ? "var(--neutral-6)" : colorOf(link.source);
  const total = layout.total;
  const sourceValue = (id: string) => nodeById.get(id)?.value ?? 0;

  const describeNode = (id: string) => {
    const node = nodeById.get(id);
    if (!node) return "";
    const out = layout.links.filter(link => link.source === id).map(link => `${nodeById.get(link.target)?.label ?? ""} ${flowValueText(kind, link.value)}`);
    return `${nodeTip(kind, node.label, node.value, total)}${out.length ? `, şuraya akıyor: ${out.join(", ")}` : ""}`;
  };

  const showNodeTip = (id: string, event?: PointerEvent) => {
    const node = nodeById.get(id);
    if (!node || !box.current) return;
    const rect = box.current.getBoundingClientRect();
    const spot = point(alongOf(node.column) + NODE, node.start + node.size / 2);
    setTip({ x: event ? event.clientX - rect.left : spot.x, y: event ? event.clientY - rect.top : spot.y, text: nodeTip(kind, node.label, node.value, total) });
  };
  const showLinkTip = (id: string, event: PointerEvent) => {
    const link = layout.links.find(item => item.id === id);
    if (!link || !box.current) return;
    const rect = box.current.getBoundingClientRect();
    setTip({ x: event.clientX - rect.left, y: event.clientY - rect.top, text: linkTip(kind, nodeById.get(link.source)?.label ?? "", nodeById.get(link.target)?.label ?? "", link.value, sourceValue(link.source)) });
  };
  const clear = () => { setFocus(null); setTip(null); };

  const byColumn = useMemo(() => Array.from({ length: layout.columns }, (_, at) => layout.nodes.filter(node => node.column === at).sort((a, b) => a.order - b.order)), [layout]);
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") { clear(); onSelectedChange?.(null); return; }
    if ((event.key === "Enter" || event.key === " ") && focus?.type === "node") { event.preventDefault(); onSelectedChange?.(focus.id === selectedId ? null : focus.id); return; }
    const current = focus?.type === "node" ? nodeById.get(focus.id) : undefined;
    let next = current;
    if (!current) next = byColumn[0]?.[0];
    else if (event.key === "ArrowDown") next = byColumn[current.column]?.[current.order + 1] ?? current;
    else if (event.key === "ArrowUp") next = byColumn[current.column]?.[current.order - 1] ?? current;
    else if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      const list = byColumn[current.column + (event.key === "ArrowRight" ? 1 : -1)];
      const here = current.start + current.size / 2;
      next = list?.reduce((best, node) => Math.abs(node.start + node.size / 2 - here) < Math.abs(best.start + best.size / 2 - here) ? node : best) ?? current;
    }
    else if (event.key === "Home") next = byColumn[0]?.[0];
    else if (event.key === "End") next = byColumn[layout.columns - 1]?.[0];
    else return;
    event.preventDefault();
    if (next) { setFocus({ type: "node", id: next.id }); showNodeTip(next.id); }
  };

  if (loading) return <figure className={styles.figure} aria-busy="true" aria-label={`${label} yükleniyor`}><div className={styles.skeleton} /></figure>;

  const curve = (link: (typeof layout.links)[number]) => {
    const from = nodeById.get(link.source)!, to = nodeById.get(link.target)!;
    const a0 = alongOf(from.column) + NODE, a1 = alongOf(to.column), mid = (a0 + a1) / 2;
    const p0 = point(a0, link.sourceAt), c0 = point(mid, link.sourceAt), c1 = point(mid, link.targetAt), p1 = point(a1, link.targetAt);
    return `M${p0.x} ${p0.y}C${c0.x} ${c0.y} ${c1.x} ${c1.y} ${p1.x} ${p1.y}`;
  };
  const showHeads = !vertical && columnLabels && columnLabels.length > 0 && width > 520;
  const svgHeight = vertical ? length : HEIGHT;
  const live = focus?.type === "node" ? describeNode(focus.id) : "";
  const motionOn = flow && !reduced && onScreen && revealed;

  return <figure ref={visibleRef} className={styles.figure} data-reduced={reduced || undefined} aria-labelledby={titleId}>
    {bare ? <h3 className={styles.srOnly} id={titleId}>{label}</h3> : <div className={styles.head}>
      <div className={styles.titles}>
        <figcaption id={titleId} className={styles.title}>{label}</figcaption>
        {description && <p className={styles.description}>{description}</p>}
      </div>
      {actions && <div className={styles.actions}>{actions}</div>}
    </div>}
    {layout.nodes.length === 0 ? <p className={styles.empty}>{emptyText}</p> : <>
      {showHeads && <div className={styles.heads} aria-hidden="true">{byColumn.map((_, at) => <span key={at} className={styles.headLabel} style={{ left: alongOf(at) + NODE / 2 }}>{columnLabels![at] ?? ""}</span>)}</div>}
      <div ref={box} className={styles.stage} onPointerLeave={clear}>
        <div className={styles.focus} role="group" aria-roledescription="akış şeması" aria-label={`${label}; ok tuşlarıyla düğümler arasında gezin`} tabIndex={0} onKeyDown={onKeyDown} onBlur={clear}>
          <svg className={styles.svg} width={length} height={svgHeight} viewBox={`0 0 ${length} ${svgHeight}`} aria-hidden="true" data-revealed={revealed || undefined}>
            <g className={styles.ribbons}>
              {layout.links.map(link => {
                const lit = through ? through.links.has(link.id) : false;
                return <path key={link.id} className={styles.ribbon} d={curve(link)} style={{ stroke: linkColor(link), strokeWidth: Math.max(1, link.thickness) }}
                  data-lit={lit || undefined} data-dim={(through && !lit) || undefined}
                  onPointerEnter={event => { setFocus({ type: "link", id: link.id }); showLinkTip(link.id, event); }} onPointerMove={event => showLinkTip(link.id, event)} />;
              })}
            </g>
            {motionOn && <g className={styles.dots}>{layout.links.map(link => {
              const count = Math.min(3, Math.max(1, Math.round(link.thickness / 8)));
              return Array.from({ length: count }, (_, at) => <circle key={`${link.id}:${at}`} r={2} className={styles.dot}>
                <animateMotion dur={`${6 + (at % 3)}s`} begin={`${-(at * 2.3)}s`} repeatCount="indefinite" path={curve(link)} />
              </circle>);
            })}</g>}
            {layout.nodes.map(node => {
              const at = point(alongOf(node.column), node.start);
              const lit = through ? through.nodes.has(node.id) : false;
              const first = node.column === 0, last = node.column === layout.columns - 1;
              const textX = vertical ? at.x : first && !vertical ? at.x - 6 : at.x + NODE + 6;
              const anchor = !vertical && first ? "end" : "start";
              const textY = vertical ? at.y - 6 : at.y + node.size / 2;
              return <g key={node.id} className={styles.node} data-lit={lit || undefined} data-dim={(through && !lit) || undefined} data-selected={((focus?.type === "node" && focus.id === node.id) || selectedId === node.id) || undefined}
                onClick={() => onSelectedChange?.(node.id === selectedId ? null : node.id)} onPointerEnter={event => { setFocus({ type: "node", id: node.id }); showNodeTip(node.id, event); }} onPointerMove={event => showNodeTip(node.id, event)}>
                <rect className={styles.rect} x={at.x} y={at.y} width={vertical ? node.size : NODE} height={vertical ? NODE : node.size} rx={3} style={{ fill: colorOf(node.id) }} />
                {(node.size >= 14 || vertical) && <text className={styles.nodeText} x={textX} y={textY} textAnchor={last && !vertical ? "start" : anchor} dominantBaseline={vertical ? "auto" : "middle"}>
                  <tspan className={styles.nodeName}>{node.label}</tspan><tspan className={styles.nodeValue} dx={6}>{flowShortText(kind, node.value)}</tspan>
                </text>}
              </g>;
            })}
          </svg>
        </div>
        {tip && <div className={styles.tip} style={{ left: tip.x, top: tip.y }} role="presentation">{tip.text}</div>}
      </div>
      <Switch label="Akış" checked={flow} onCheckedChange={setFlow} />
    </>}
    <div className={styles.srOnly}><table>
      <caption>{label}</caption>
      <thead><tr><th scope="col">Kaynak</th><th scope="col">Hedef</th><th scope="col">Değer</th><th scope="col">Kaynağa göre pay</th></tr></thead>
      <tbody>{layout.links.map(link => <tr key={link.id}><th scope="row">{nodeById.get(link.source)?.label}</th><td>{nodeById.get(link.target)?.label}</td><td>{flowValueText(kind, link.value)}</td><td>{flowShareText(link.value, sourceValue(link.source))}</td></tr>)}</tbody>
    </table></div>
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{live}</p>
  </figure>;
}

export default SankeyFlow;
